<script setup>
import {computed,reactive,ref} from 'vue'
import {shop,notificar} from '../stores/shop'
import {enviarMensaje,mensajeError} from '../services/api'
import {storage} from '../services/storage'
const base=import.meta.env.BASE_URL
const hoy=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10)
const draft=storage.get('borrador',{})
const form=reactive({nombre:draft.nombre||'',email:draft.email||'',tel:draft.tel||'',motivo:draft.motivo||'',fecha:draft.fecha||'',cant:draft.cant||1,msg:draft.msg||'',ok:!!draft.ok})
const touched=reactive({}), enviando=ref(false), estado=ref({tipo:'',texto:''})
const errores=computed(()=>({nombre:form.nombre.trim().length<3||!/^[A-Za-zÁÉÍÓÚáéíóúÑñ ]+$/.test(form.nombre)?'Escribe un nombre válido (mínimo 3 letras).':'',email:!/^\S+@\S+\.\S+$/.test(form.email)?'Escribe un correo válido.':'',tel:!/^3\d{9}$/.test(form.tel)?'Usa 10 dígitos y comienza por 3.':'',motivo:!form.motivo?'Selecciona un motivo.':'',fecha:form.fecha&&form.fecha<hoy?'Elige una fecha desde hoy.':'',cant:form.cant<1||form.cant>20?'La cantidad debe estar entre 1 y 20.':'',msg:form.msg.trim().length<10?'Escribe al menos 10 caracteres.':form.msg.length>300?'Máximo 300 caracteres.':'',ok:!form.ok?'Debes aceptar para continuar.':''}))
function valido(campo){return !errores.value[campo]}
function tocar(c){touched[c]=true;storage.set('borrador',form)}
async function enviar(){Object.keys(errores.value).forEach(k=>touched[k]=true);if(Object.values(errores.value).some(Boolean)){estado.value={tipo:'error',texto:'Revisa los campos marcados antes de enviar.'};return}enviando.value=true;estado.value={tipo:'info',texto:'Enviando tu mensaje…'};try{const respuesta=await enviarMensaje(form);shop.mensajes.unshift({id:Date.now(),nombre:form.nombre,email:form.email,motivo:form.motivo,msg:form.msg,fecha:new Date().toISOString()});storage.set('mensajes',shop.mensajes);storage.remove('borrador');Object.assign(form,{nombre:'',email:'',tel:'',motivo:'',fecha:'',cant:1,msg:'',ok:false});Object.keys(touched).forEach(k=>delete touched[k]);estado.value={tipo:'ok',texto:`¡Mensaje enviado! Código de confirmación ${respuesta.id}.`};notificar('Mensaje enviado y guardado')}catch(e){estado.value={tipo:'error',texto:mensajeError(e)+' Tus datos siguen guardados para que lo intentes otra vez.'}}finally{enviando.value=false}}
function eliminar(id){shop.mensajes=shop.mensajes.filter(m=>m.id!==id);storage.set('mensajes',shop.mensajes)}
function limpiar(){shop.mensajes=[];storage.set('mensajes',[])}</script>
<template><section class="view"><section class="contact-hero"><div class="contact-photo"><picture><source media="(max-width: 639px)" :srcset="base+'img/tienda-interior-movil.jpg'"><img :src="base+'img/tienda-interior.jpg'" alt="Interior de la tienda Stilo & Moda"></picture><div class="overlay-text"><p class="big">Viste con Estilo</p><RouterLink class="btn btn--soft" to="/tienda">Explorar tienda</RouterLink></div></div><div class="contact-info"><h1 class="sr-only">Contacto</h1><ul class="info"><li><i class="fa-solid fa-location-dot"></i><div><strong>Ubicación</strong><span>Avenida Primera 15-43</span></div></li><li><i class="fa-brands fa-whatsapp"></i><div><strong>WhatsApp</strong><span>+57 300 000 0000</span></div></li><li><i class="fa-regular fa-envelope"></i><div><strong>Correo</strong><span>empresa@gmail.com</span></div></li><li><i class="fa-regular fa-clock"></i><div><strong>Horario de atención</strong><span>De lunes a viernes de 7 a. m. a 6 p. m.</span></div></li></ul></div></section>
<section class="section section--pink"><form class="contact-form" novalidate @submit.prevent="enviar"><h2>Envíanos un mensaje</h2><div class="form-grid"><div class="field" :class="{'is-invalid':touched.nombre&&errores.nombre,'is-valid':touched.nombre&&!errores.nombre}"><label for="nombre">Nombre completo</label><input id="nombre" v-model="form.nombre" @input="tocar('nombre')" type="text" placeholder="Tu nombre"><small v-if="touched.nombre&&errores.nombre" class="field-error">{{errores.nombre}}</small></div><div class="field" :class="{'is-invalid':touched.email&&errores.email,'is-valid':touched.email&&!errores.email}"><label for="email">Correo electrónico</label><input id="email" v-model="form.email" @input="tocar('email')" type="email" placeholder="tu@correo.com"><small v-if="touched.email&&errores.email" class="field-error">{{errores.email}}</small></div><div class="field" :class="{'is-invalid':touched.tel&&errores.tel,'is-valid':touched.tel&&!errores.tel}"><label for="tel">Teléfono</label><input id="tel" v-model="form.tel" @input="tocar('tel')" type="tel" placeholder="3001234567"><small v-if="touched.tel&&errores.tel" class="field-error">{{errores.tel}}</small></div><div class="field" :class="{'is-invalid':touched.motivo&&errores.motivo}"><label for="motivo">Motivo</label><select id="motivo" v-model="form.motivo" @change="tocar('motivo')"><option value="">Selecciona uno</option><option>Consulta de talla</option><option>Estado de un pedido</option><option>Otro</option></select><small v-if="touched.motivo&&errores.motivo" class="field-error">{{errores.motivo}}</small></div><div class="field"><label for="fecha">Fecha de visita (opcional)</label><input id="fecha" v-model="form.fecha" @change="tocar('fecha')" type="date" :min="hoy"><small v-if="touched.fecha&&errores.fecha" class="field-error">{{errores.fecha}}</small></div><div class="field"><label for="cant">Prendas de interés</label><input id="cant" v-model.number="form.cant" @input="tocar('cant')" type="number" min="1" max="20"><small v-if="touched.cant&&errores.cant" class="field-error">{{errores.cant}}</small></div></div><div class="field"><label for="msg">Mensaje</label><textarea id="msg" v-model="form.msg" @input="tocar('msg')" rows="4" maxlength="300" placeholder="Cuéntanos en qué podemos ayudarte"></textarea><small class="contador">{{form.msg.length}}/300</small><small v-if="touched.msg&&errores.msg" class="field-error">{{errores.msg}}</small></div><label class="check"><input v-model="form.ok" @change="tocar('ok')" type="checkbox"> Acepto que Stilo &amp; Moda me contacte por estos datos.</label><small v-if="touched.ok&&errores.ok" class="field-error">{{errores.ok}}</small><div v-if="estado.texto" class="form-status" :class="'form-status--'+estado.tipo" role="status">{{estado.texto}}</div><button class="btn" type="submit" :disabled="enviando">{{enviando?'Enviando…':'Enviar mensaje'}}</button></form></section>
<section class="section"><div class="msg-wrap"><header class="msg-head"><h2>Mensajes enviados</h2><button class="btn btn--ghost btn--sm" type="button" @click="limpiar" :disabled="!shop.mensajes.length">Vaciar historial</button></header><ul class="msg-list"><li v-for="m in shop.mensajes" :key="m.id" class="msg-item"><div><strong>{{m.motivo}}</strong><small>{{m.nombre}}, {{new Date(m.fecha).toLocaleString('es-CO')}}</small><p>{{m.msg}}</p></div><button class="btn btn--ghost btn--sm" type="button" @click="eliminar(m.id)">Eliminar</button></li><li v-if="!shop.mensajes.length" class="msg-empty">Aún no has enviado mensajes.</li></ul></div></section></section></template>
